"""Report frozen residual-only results, including the matched version ablation."""
import json
from .pipeline import ROOT
from .scenario_study import sha


def report(s, directory):
    sel=s['selection']; candidate=sel['diagnostic']; matched=sel['matched_uniform']
    lines=['# Давность и версии GFS только в диапазоне ошибки','',
      'Точечный прогноз и детектор сохранены. Проверены 26 вариантов диапазона: прежние две базы, три головы на исходном архиве и семь политик × три головы на совместимом расширенном архиве. Выбор только по 2023–2024 оставил risk_5_lower_95. Новый кандидат лучше прежнего диапазона по части показателей 2025, но хуже на холодных ночах 2026 и не выиграл валидационный выбор. В поле не подключён.','',
      '## Что меняется в модели','',
      'Ошибка = фактический минимум минус исходный точечный прогноз. Для 2022–2023 ошибки получены тем же невзвешенным Huber на шести исключаемых блоках целых ночей. Возрастные веса, веса исторических версий и индикаторы версии применяются только к модели этих ошибок. Финальный точечный прогноз всегда читается из исходного неизменного huber_1.json. Выпуск GFS 06 UTC и все 14 часов ночи, горизонты 10–23, остаются прежними.',
      'Головы: Ridge100 для log(1+|ошибка|), Ridge10 для раздельных хвостов, квантильные деревья 0.05/0.95 (100 деревьев, глубина 2, лист от 20, learning rate 0.05). Политики: равные веса; полупериод давности 1/2 сезона; веса версий 0.25/0.5/1; давность × версия; индикаторы исторического режима; индикаторы × давность × версия. Веса зависят от года обучения и выпуска, не от фактического холода.','',
      '## Совместимость старого архива','',
      'У прежней модели 15 признаков, включая мгновенную общую облачность. Все девять дополнительных холодных ночей начала 2021 лежат до обновления GFSv16 и не имеют этого поля. Усреднённая облачность не заменяет мгновенную. Эти 22 прогнозные ночи исключены: получить для них ошибку исходного точечного прогноза без замены входов нельзя.',
      'Совместимый архив 23 марта — 31 мая 2021: 70 прогнозных ночей, 69 полных фактических, ни одной холодной. Модель ошибки обучается на 253 полных ночах вместо 184; число холодных остаётся 21 (18 в 2022, 3 в 2023). Поэтому результат не означает проверки всех девяти старых холодных ночей при сохранении исходной точки.',
      'Ошибки дополнительных ночей 2021 рассчитаны исходной моделью соответствующего валидационного фолда, обученной на 2022 либо 2022–2023 без этих ночей. Это ретроспективное использование исторического архива; не прогноз, выпущенный в 2021. Новая точечная модель для них не обучается.','',
      '## Хронология и выбор','',
      'Фолды: точка и OOF ошибки 2022 → проверка 2023; точка и OOF ошибки 2022–2023 → проверка 2024. Совместимый 2021 добавляется только в обучение головы ошибки. Калибровка невзвешенная, целевая 90%; на валидации исключает проверяемую ночь из пула того же сезона. Финальная калибровка — 2024, минимум 30 ночей. Другие, в том числе более поздние даты того же валидационного сезона, присутствуют в LOO пуле: это ретроспективная проверка, не последовательный рабочий выпуск.',
      'Ограничения: общее покрытие не ниже симметричной базы; средняя ширина тёплых ночей не выше 1.05× базы; общая ширина не выше 1.05× прежнего холодного диапазона. MAE обязана точно совпасть у всех вариантов. Среди допустимых: минимальная доля непокрытых холодных ночей, затем среднее штрафов холодных/тёплых, затем ширина и порядок регистра.',
      'Кандидат и парный вариант без учёта версии зафиксированы до открытия контрольных лет. 2025–2026 ранее просмотрены в других исследованиях: исключены из обучения, выбора и калибровки, но новым слепым тестом не являются.','',
      '| Вариант | Холодные | Все покрытые | Ширина всех, °C | Ширина холодных, °C | Штраф холодных | Допустим |',
      '|---|---:|---:|---:|---:|---:|---|']
    for name,r in sel['pooled_validation'].items():
        lines.append(f"| {name} | {r['cold_covered']}/{r['cold_nights']} | {r['covered']}/{r['nights']} | {r['mean_width_c']:.3f} | {r['cold_mean_width_c']:.3f} | {r['cold_interval_score']:.3f} | {'да' if all(sel['gates'][name].values()) else 'нет'} |")
    lines+=['',f'Выбран {sel["winner"]}. Диагностический кандидат {candidate}; парный {matched}.',
      'Кандидат проходит ограничения, но покрывает 6/7 холодных ночей против 7/7 у прежнего диапазона. Давность сама по себе не дала победителя. У версии относительно того же алгоритма без неё холодное покрытие одинаковое 6/7, средняя ширина 5.121→5.110°C, холодный штраф 7.529→7.586: устойчивого преимущества версии нет.',
      'В фолде 2023 новый режим отсутствовал в обучении: все 92 ночи отмечены unseen_regime. Они остаются в исследовательской таблице, но safe_prediction не разрешает их скорректированную выдачу. Финальное обучение включает 2023; в контроле неизвестных режимов нет.','',
      '## Контроль после фиксации','',
      '| Год | Метод | Холодные | Все покрытые | MAE точки, °C | Ширина всех, °C | Ширина холодных, °C | Штраф холодных |',
      '|---|---|---:|---:|---:|---:|---:|---:|']
    labels={'gfs':'GFS + ошибка2024','legacy_huber':'Исходный Huber + симметричная ошибка',
      'previous_cold_range':'Прежний выбранный диапазон','matched_uniform':'Та же голова и архив без версии',
      'error_only_candidate':'Версия только в ошибке · кандидат'}
    for year,season in s['seasons'].items():
        for name,label in labels.items():
            r=season['scores'][name]
            lines.append(f"| {year} | {label} | {r['cold_covered']}/{r['cold_nights']} | {r['covered']}/{r['nights']} | {r['mae_c']:.3f} | {r['mean_width_c']:.3f} | {r['cold_mean_width_c']:.3f} | {r['cold_interval_score']:.3f} |")
    lines+=['','Штраф (interval score90) = ширина + 20×выход факта за границу; меньше лучше. Диапазон GFS — отдельная калибровка ошибки 2024, не собственный ансамбль GFS.',
      'Относительно прежнего диапазона кандидат в 2025 повышает холодное покрытие 3/6→4/6 и уменьшает общую ширину 6.125→5.403°C (−11.8%); холодный штраф 15.532→13.111 снижается. Две холодные ночи остаются за нижней границей. В 2026 холодное покрытие 4/4 сохраняется, общая ширина 6.136→5.194°C (−15.4%), но холодная ширина/штраф 6.404→7.066 ухудшаются, общее покрытие 84/86→83/86.',
      'Этот выигрыш 2025 нельзя приписать версии: парная голова на том же архиве без версии также покрывает 4/6 и имеет холодный штраф 13.035, немного лучше версии 13.111. Версия сужает среднюю ширину всего на 0.026°C в 2025 и 0.029°C в 2026. В 2025 общее покрытие падает 85/91→84/91 относительно парного варианта; в 2026 остаётся 83/86. Эффект смены семейства диапазона заметнее, чем изолированный эффект индикаторов версии.',
      'Прежний выбранный диапазон оставлен по заранее заданному критерию 2023–2024. Новый вариант не выбран по удачному 2025 и не пересобран после просмотра 2026.','',
      '## Неизменность точки и детектора','',
      '| Год | Проверено точек | Проверено масок/времён | Найдено заморозков | Пропуски | Ложные тревоги |',
      '|---|---:|---:|---:|---:|---:|']
    for year,season in s['seasons'].items():
        d=season['detector'];lines.append(f"| {year} | {season['point_values_verified']} | {season['detector_masks_verified']} | {d.get('hits',0)} | {d.get('misses',0)} | {d.get('false_alarms',0)} |")
    lines+=['','Все 184 точечных прогноза выбранного и обоих исследовательских вариантов точно совпали с исходными. Все 184 маски 14 часов, начало и длительность заморозка совпали с прежними снимками event_duration_weather@0.25. Семь ночей с неполным фактом не заполнялись; их прогнозы тоже проверены на неизменность.',
      '## Ограничения продукта и следующий шаг','',
      'Диапазон ошибки минимума не меняет вероятность/событие, выдаваемые прежним детектором, и не задаёт почасовой диапазон, начало или длительность. Номинальные 90% не являются гарантией холодного покрытия, вероятностью повреждения яблони или доказанной переносимостью в сад. На валидации всего семь холодных ночей, на контроле десять, соседние погодные события зависимы; настройки и калибровка используют одни валидационные сезоны.',
      'safe_prediction отвергает другой сайт, отсутствие мгновенной облачности, неверный выпуск/горизонт/сезон, дату вне реестра, не виденный в обучении режим и признаки вне области обучения (max |z| > 4). Все такие ночи остаются в исследовательских метриках, а не скрываются ради улучшения покрытия. В контроле 5/1 ночей отмечены OOD. Реестр версий укрупнённый, не учитывает каждый оперативный патч.',
      'В поле сохранён GFS. Локация сада не выбрана; паспорт, журнал решений и комплект пользовательского тестирования не изменены. Следующий полезный источник информации — дополнительные совместимые холодные события с полным набором GFS и независимая перспективная локальная проверка. Текущий результат не обосновывает дальнейший подбор на 2025–2026.','',
      '## Воспроизведение','',
      '    .\\.venv\\Scripts\\python.exe -X utf8 -m agro_checker.fixed_point_error_study --select-only',
      '    .\\.venv\\Scripts\\python.exe -X utf8 -m agro_checker.fixed_point_error_study',
      '    .\\.venv\\Scripts\\python.exe -X utf8 -m agro_checker.fixed_point_error_report','',
      'При повторе проверяются SHA протокола, исходного кода, родителей, прежних выборов, данных и моделей. Замороженные learner/selector и их зависимости не редактировать; новый эксперимент требует нового протокола/каталога.',
      'Выбор зафиксирован: '+sel['selection_saved_at_utc']+'.',
      'SHA выбора: '+s['selection_sha256']+'.',
      'SHA прогнозных кадров: '+s['forecast_sha256']+'.',
      'SHA исходной точки: '+sel['parent_hashes']['point_model']+'.','',
      '[Численные результаты](FIXED_POINT_ERROR_SUMMARY.json). [График](assets/fixed-point-error-quality.png). [Предыдущий эксперимент с переобучением точки](REGIME_ERROR_REPORT.md).','',
      'Границы режимов: [NOAA/EMC GFSv16](https://www.emc.ncep.noaa.gov/emc/pages/numerical_forecast_systems/gfs/implementations.php), [NWS SCN22-104](https://www.weather.gov/media/notification/pdf2/scn22-104_gfs.v16.3.0_aaa.pdf).']
    (directory/'FIXED_POINT_ERROR_REPORT.md').write_text('\n'.join(lines)+'\n',encoding='utf-8')


def figure(s,directory):
    import matplotlib
    matplotlib.use('Agg')
    import matplotlib.pyplot as plt
    names=['previous_cold_range','matched_uniform','error_only_candidate']
    labels=['Прежний диапазон','Та же голова\nбез версии','Версия только\nв ошибке']
    colors=['#36704e','#7390a2','#9261a5']
    fig,axes=plt.subplots(1,3,figsize=(13.8,4.9));fig.patch.set_facecolor('#f2f5ef')
    for ax,(title,key) in zip(axes,[('Покрытие холодных ночей','cold_coverage'),('Средняя ширина всех, °C','mean_width_c'),('Штраф холодных ночей ↓','cold_interval_score')]):
        for j,name in enumerate(names):
            rows=[s['seasons'][y]['scores'][name] for y in ['2025','2026']];values=[r[key] for r in rows];positions=[k+(j-1)*.24 for k in [0,1]]
            ax.bar(positions,values,.24,color=colors[j],label=labels[j])
            for x,v,r in zip(positions,values,rows):
                label=f"{r['cold_covered']}/{r['cold_nights']}" if key=='cold_coverage' else f'{v:.2f}'
                ax.text(x,v+.015 if key=='cold_coverage' else v*1.015,label,ha='center',fontsize=9)
        ax.set_xticks([0,1],['2025','2026']);ax.set_title(title,fontsize=12);ax.spines[['top','right']].set_visible(False);ax.grid(axis='y',alpha=.15);ax.set_axisbelow(True)
        if key=='cold_coverage':ax.set_ylim(0,1.15);ax.set_yticks([0,.25,.5,.75,1],['0%','25%','50%','75%','100%'])
        else:ax.set_ylim(0,ax.get_ylim()[1]*1.1)
    handles,legend=axes[0].get_legend_handles_labels();fig.legend(handles,legend,loc='lower center',ncol=3,frameon=False,bbox_to_anchor=(.5,.07))
    fig.suptitle('Диапазон ошибки: точка и детектор неизменны',fontsize=15,y=.98)
    fig.text(.5,.02,'Выбор по 2023–2024 сохранил прежний диапазон. Эффект самой версии мал; новый кандидат — исследование.',ha='center',fontsize=10)
    fig.tight_layout(rect=[0,.22,1,.93]);directory.mkdir(parents=True,exist_ok=True);fig.savefig(directory/'fixed-point-error-quality.png',dpi=150);plt.close(fig)


if __name__=='__main__':
    s=json.loads((ROOT/'docs/FIXED_POINT_ERROR_SUMMARY.json').read_text(encoding='utf-8'))
    if sha(ROOT/'data/processed/fixed-point-error-study/night-forecasts.json')!=s['forecast_sha256']:raise ValueError('Frozen forecasts changed')
    from .fixed_point_error_study import selection
    if selection(ROOT/'config/fixed_point_error.json',ROOT/'data')!=s['selection']:raise ValueError('Frozen choice changed')
    report(s,ROOT/'docs');figure(s,ROOT/'docs/assets')
    print('Report and figure saved; selected:',s['selection']['winner'])
